def _init_value(dtype):
    if dtype.is_floating_point:
        return float("inf")
    return int(torch.iinfo(dtype).max)


# Path A: inner==1, one program per contiguous group; fused reduce + broadcast.
@triton.jit
def fused_contig_kernel(
    inp_ptr, red, BLOCK_R: tl.constexpr, INIT: tl.constexpr, DTYPE: tl.constexpr
):
    pid = tl.program_id(0)
    base = pid.to(tl.int64) * red
    acc = tl.full([BLOCK_R], INIT, dtype=DTYPE)
    num = (red + BLOCK_R - 1) // BLOCK_R
    for k in range(0, num):
        offs = k * BLOCK_R + tl.arange(0, BLOCK_R)
        mask = offs < red
        x = tl.load(inp_ptr + base + offs.to(tl.int64), mask=mask, other=INIT).to(DTYPE)
        acc = tl.minimum(acc, x).to(DTYPE)
    res = tl.min(acc, axis=0)
    res_vec = res + tl.zeros([BLOCK_R], dtype=DTYPE)
    for k in range(0, num):
        offs = k * BLOCK_R + tl.arange(0, BLOCK_R)
        mask = offs < red
        tl.store(inp_ptr + base + offs.to(tl.int64), res_vec, mask=mask)


# Path A-2D: inner==1, process BLOCK_M rows x BLOCK_N cols per program so
# independent row loads overlap the vector min and the store. red must fit BLOCK_N.
