        rr = rows + k
        rmask = rr < red
        offs = slab + rr.to(tl.int64)[:, None] * inner + col
        tile_mask = rmask[:, None] & mask_i[None, :]
        tl.store(inp_ptr + offs, acc2d, mask=tile_mask)


