# Path B split reduction (inner==1, tiny outer, huge red).
@triton.jit
def reduce_split_kernel(
    inp_ptr,
    partials_ptr,
    red,
    num_splits,
    chunk,
    BLOCK_R: tl.constexpr,
    INIT: tl.constexpr,
    DTYPE: tl.constexpr,
):
    pid = tl.program_id(0)
    m = pid // num_splits
    s = pid % num_splits
    base = m.to(tl.int64) * red
    start = s * chunk
    stop = start + chunk
    acc = tl.full([BLOCK_R], INIT, dtype=DTYPE)
    num = (chunk + BLOCK_R - 1) // BLOCK_R
    for k in range(0, num):
        offs = start + k * BLOCK_R + tl.arange(0, BLOCK_R)
        mask = (offs < red) & (offs < stop)
        x = tl.load(inp_ptr + base + offs.to(tl.int64), mask=mask, other=INIT).to(DTYPE)
        acc = tl.minimum(acc, x).to(DTYPE)
    res = tl.min(acc, axis=0)
    tl.store(partials_ptr + pid, res)


@triton.jit
def combine_kernel(
    partials_ptr,
    mins_ptr,
    num_splits,
    BLOCK_S: tl.constexpr,
    INIT: tl.constexpr,
    DTYPE: tl.constexpr,
):
    m = tl.program_id(0)
    offs = tl.arange(0, BLOCK_S)
    mask = offs < num_splits
    x = tl.load(partials_ptr + m * num_splits + offs, mask=mask, other=INIT).to(DTYPE)
    res = tl.min(x, axis=0)
    tl.store(mins_ptr + m, res)


# Path B broadcast: group index == program_id(0), no div/mod.
@triton.jit
def broadcast_group_kernel(
    inp_ptr, mins_ptr, red, BLOCK: tl.constexpr, DTYPE: tl.constexpr
):
    o = tl.program_id(0)
    j = tl.program_id(1) * BLOCK
    offs = j + tl.arange(0, BLOCK)
    mask = offs < red
    m = tl.load(mins_ptr + o).to(DTYPE)
    base = o.to(tl.int64) * red
    m_vec = m + tl.zeros([BLOCK], dtype=DTYPE)
    tl.store(inp_ptr + base + offs.to(tl.int64), m_vec, mask=mask)


def amin_(inp, dim=None, keepdim=False):
    ndim = inp.dim()
    numel = inp.numel()
    if numel == 0:
        return inp

    if dim is None:
        dims = list(range(ndim))
    elif isinstance(dim, int):
        dims = [dim % ndim]
    else:
        dims = sorted(set(d % ndim for d in dim))
    dims = sorted(set(dims))

    if len(dims) == ndim or ndim == 0:
        outer, red, inner = 1, numel, 1
    else:
        first, last = dims[0], dims[-1]
        outer = 1
        for a in range(0, first):
            outer *= inp.shape[a]
        red = 1
        for a in range(first, last + 1):
            red *= inp.shape[a]
        inner = 1
        for a in range(last + 1, ndim):
            inner *= inp.shape[a]

    dev = inp.device
    tl_dtype = _TL_DTYPE[inp.dtype]
    init_val = _init_value(inp.dtype)

    if inner == 1:
        if outer <= 8 and red >= 65536:
            MIN_CHUNK = 8192
            num_splits = max(1, min(4096, triton.cdiv(red, MIN_CHUNK)))
            chunk = triton.cdiv(red, num_splits)
            mins = torch.empty(outer, dtype=inp.dtype, device=dev)
            partials = torch.empty(outer * num_splits, dtype=inp.dtype, device=dev)
            reduce_split_kernel[(outer * num_splits,)](
                inp,
                partials,
                red,
                num_splits,
                chunk,
                BLOCK_R=1024,
                INIT=init_val,
                DTYPE=tl_dtype,
            )
            BLOCK_S = max(1, triton.next_power_of_2(num_splits))
            combine_kernel[(outer,)](
                partials,
                mins,
                num_splits,
                BLOCK_S=BLOCK_S,
                INIT=init_val,
                DTYPE=tl_dtype,
            )
            BLOCK = 1024
            broadcast_group_kernel[(outer, triton.cdiv(red, BLOCK))](
                inp, mins, red, BLOCK=BLOCK, DTYPE=tl_dtype
            )
        elif outer >= 64:
            # 2D multi-row path: process BLOCK_M rows/program, tiling columns by
            # BLOCK_N so independent row loads overlap the min and store.
            BLOCK_N = min(triton.next_power_of_2(int(red)), 1024)
            BLOCK_M = 8
            grid = (triton.cdiv(outer, BLOCK_M),)
            fused_contig2d_kernel[grid](
                inp,
                outer,
                red,
                BLOCK_M=BLOCK_M,
                BLOCK_N=BLOCK_N,
                INIT=init_val,
                DTYPE=tl_dtype,
            )
        else:
            BLOCK_R = 1024
            fused_contig_kernel[(outer,)](
                inp, red, BLOCK_R=BLOCK_R, INIT=init_val, DTYPE=tl_dtype
            )
    else:
        BLOCK_I = min(triton.next_power_of_2(inner), 2048)
        BLOCK_I = max(BLOCK_I, 64)
        inner_blocks = triton.cdiv(inner, BLOCK_I)
        base_programs = outer * inner_blocks
        # Split the reduction dim to raise program count while keeping large
        # contiguous inner transactions, when base parallelism is low and red is large.
        if base_programs < 256 and red >= 64:
            red_splits = max(1, min(red, (256 + base_programs - 1) // base_programs))
            rchunk = triton.cdiv(red, red_splits)
            red_splits = triton.cdiv(red, rchunk)
            if red_splits > 1:
                mins = torch.empty(outer * inner, dtype=inp.dtype, device=dev)
                partials = torch.empty(
                    outer * red_splits * inner, dtype=inp.dtype, device=dev
                )
                reduce_strided_split_kernel[(outer, red_splits, inner_blocks)](
                    inp,
                    partials,
                    red,
                    inner,
                    red_splits,
                    rchunk,
                    BLOCK_I=BLOCK_I,
                    BLOCK_R=8,
                    INIT=init_val,
                    DTYPE=tl_dtype,
                )
                combine_strided_kernel[(outer, inner_blocks)](
                    partials,
                    mins,
                    inner,
                    red_splits,
                    BLOCK_I=BLOCK_I,
                    INIT=init_val,
                    DTYPE=tl_dtype,
                )
                broadcast_strided_kernel[(outer, inner_blocks)](
                    inp, mins, red, inner, BLOCK_I=BLOCK_I, BLOCK_R=8, DTYPE=tl_dtype
                )
                return inp
        grid = (outer, inner_blocks)
        fused_strided_kernel[grid](
            inp, red, inner, BLOCK_I=BLOCK_I, BLOCK_R=8, INIT=init_val, DTYPE=tl_dtype
        )

    return inp
